--region lifecycle
function CardProgressionEquipmentRecastAutoDialog:__init()
    self._filterClass  = nil
    self._allScreenVo  = nil
    self._toggleState  = {}
    self._toggleNodes  = {}
end

function CardProgressionEquipmentRecastAutoDialog:__delete()
    self._filterClass  = nil
    self._allScreenVo  = nil
    self._toggleState  = nil
    self._toggleNodes  = nil
end

