--region init
function CardProgressionEquipmentRecastAutoDialog:InitHandler()
    SetButtonAction(self.BtnClose, Bind(self, self.BtnCloseOnClickHandler))
    SetButtonAction(self.ButtonGroup, Bind(self, self.BtnConfirmOnClickHandler))
end

function CardProgressionEquipmentRecastAutoDialog:InitData()
    local parameters = self.controller.Argument.parameters
    self:SetFilterClass(parameters.filterClass)

    local allScreenVo = CardConfMgr:GetInstance():GetAllScreenVo(self:GetFilterClass())
    self:SetAllScreenVo(allScreenVo)
    
    self._toggleState = {}
    self._toggleNodes = {}
    local saveData = CfUtils.GetLocalData(self:GetSaveKey(), "")
    if saveData == '' then
        saveData = {}
    else
        saveData = table.deserialize(saveData)
    end
    for _, v in ipairs(allScreenVo) do
        local data = {}
        local save = saveData[tostring(v.id)] or {}
        for i = 1, #v.condition do
            if save[v.condition[i]] then
                table.insert(data, save[v.condition[i]] == true)
            else
                table.insert(data, false)
            end
        end
        self._toggleState[tostring(v.id)] = data
        self._toggleNodes[tostring(v.id)] = {}
    end
end

function CardProgressionEquipmentRecastAutoDialog:InitView()
    self:RefreshList()
end
