--region handler
---关闭按钮点击回调处理
function CardProgressionEquipmentRecastAutoDialog:BtnCloseOnClickHandler()
    CfUtils.DialogClose(self.controller)
end

---确认按钮点击回调处理
function CardProgressionEquipmentRecastAutoDialog:BtnConfirmOnClickHandler()
    -- 要至少勾选一项保留条件
    for filterType, list in pairs(self._toggleState) do
        local isTrue = false
        for _, v in ipairs(list) do
            if v == true then
                isTrue = true
                break
            end
        end
        
        if not isTrue then
            if filterType == tostring(Constants.EquipmentAutoRecastFilterType.Attribute) then
                GameUtils.Toast(localize("请选择需要保留的属性"))
            elseif filterType == tostring(Constants.EquipmentAutoRecastFilterType.Quality) then
                GameUtils.Toast(localize("请选择需要保留的品质"))
            end
            return
        end
    end

    -- 转成需要的格式
    local filterData = {}
    for filterType, list in pairs(self._toggleState) do
        local data = {}
        local screenVo = self:GetScreenVoByType(filterType)
        for i, state in ipairs(list) do
            data[tostring(screenVo.condition[i])] = state
        end
        filterData[filterType] = data
    end

    local str = table.serialize(filterData)
    CfUtils.WriteLocalData(self:GetSaveKey(), str)
    
    Events.Broadcast(Constants.EventNames.CardProgressEquipmentRecastAuto, filterData)
    CfUtils.DialogClose(self.controller)
end

---开关点击回调处理
function CardProgressionEquipmentRecastAutoDialog:ToggleOnClickHandler(filterType, index)
    local state = not self._toggleState[tostring(filterType)][index]

    if state and filterType == Constants.EquipmentAutoRecastFilterType.Quality then
        -- 品质选项互斥
        for i, v in ipairs(self._toggleState[tostring(filterType)]) do
            if i ~= index and v then
                self._toggleState[tostring(filterType)][i] = false
                
                local node = self._toggleNodes[tostring(filterType)][i]
                if isNull(node) then return end

                local imgSymbol = node.transform:Find("BtnHook/ImgSymbol")
                if isNotNull(imgSymbol) then
                    CfUtils.SetActive(imgSymbol, false)
                end
                local imgBg = node.transform:Find("ImgBg")
                if isNotNull(imgBg) then
                    CfUtils.SetUISwitchImage(imgBg, 1)
                end
            end
        end
    end
    
    self._toggleState[tostring(filterType)][index] = state

    local node = self._toggleNodes[tostring(filterType)][index]
    if isNull(node) then return end
    
    local imgSymbol = node.transform:Find("BtnHook/ImgSymbol")
    if isNotNull(imgSymbol) then
        CfUtils.SetActive(imgSymbol, state)
    end

    local imgBg = node.transform:Find("ImgBg")
    if isNotNull(imgBg) then
        CfUtils.SetUISwitchImage(imgBg, state and 2 or 1)
    end
end
--endregion handler

--region private
---刷新列表
function CardProgressionEquipmentRecastAutoDialog:RefreshList()
    self:RefreshAttrList()
    self:RefreshQualityList()
end

---刷新属性列表
function CardProgressionEquipmentRecastAutoDialog:RefreshAttrList()
    local filterType = Constants.EquipmentAutoRecastFilterType.Attribute
    local data = self:GetScreenVoByType(filterType)
    for i, v in ipairs(data.condition) do
        local node = self._toggleNodes[tostring(filterType)][i]
        if not node then
            node = CfUtils.InstantiateGo(self.DescNode1, self.FlowLayout1)
            CfUtils.SetActive(node, true)
            self._toggleNodes[tostring(filterType)][i] = node
        end
        local btn = node.transform:Find("BtnHook")
        local text = node.transform:Find("TextDesc")
        SetButtonAction(btn, Bind(self, self.ToggleOnClickHandler, filterType, i))
        CfUtils.FillText(text, data.conditionName[i])

        local state = self._toggleState[tostring(filterType)][i]
        local imgSymbol = node.transform:Find("BtnHook/ImgSymbol")
        if isNotNull(imgSymbol) then
            CfUtils.SetActive(imgSymbol, state)
        end

        local imgBg = node.transform:Find("ImgBg")
        if isNotNull(imgBg) then
            CfUtils.SetUISwitchImage(imgBg, state and 2 or 1)
        end
    end
end

---刷新稀有度列表
function CardProgressionEquipmentRecastAutoDialog:RefreshQualityList()
    local filterType = Constants.EquipmentAutoRecastFilterType.Quality
    local data = self:GetScreenVoByType(filterType)
    for i, v in ipairs(data.condition) do
        local node = self._toggleNodes[tostring(filterType)][i]
        if not node then
            node = CfUtils.InstantiateGo(self.DescNode2, self.FlowLayout2)
            CfUtils.SetActive(node, true)
            self._toggleNodes[tostring(filterType)][i] = node
        end
        local btn = node.transform:Find("BtnHook")
        local text = node.transform:Find("TextDesc")
        local imgQuality = node.transform:Find("ImgQuality")
        SetButtonAction(btn, Bind(self, self.ToggleOnClickHandler, filterType, i))
        CfUtils.FillText(text, data.conditionName[i])
        CfUtils.SetUISwitchImage(imgQuality, checkInt(v) - 2)

        local state = self._toggleState[tostring(filterType)][i]
        local imgSymbol = node.transform:Find("BtnHook/ImgSymbol")
        if isNotNull(imgSymbol) then
            CfUtils.SetActive(imgSymbol, state)
        end

        local imgBg = node.transform:Find("ImgBg")
        if isNotNull(imgBg) then
            CfUtils.SetUISwitchImage(imgBg, state and 2 or 1)
        end
    end
end
